{"source":"#include <stdio.h>

int main(int argc, char *argv[])
{
int a,b; scanf("%d %d",&a,&b);
if(a<b){
printf("-1");
return -1;
}
if(a==b){
printf("%.10lf",(double)b);
return 0;
}

int n=a/b;
if(n%2==0)
--n;

double da=a;
double db=b;
double dotx=(da)/(db + da)*(n+1);
double x=(da)/dotx;
printf("%.12lf\n",x);

return 0;
}"}
